using System;using System.Collections.Generic;using System.Drawing;using System.Linq;using System.Windows.Forms;

// Original logical metrics are retained, as in Catalyst's EditorZoom. Never
// scale previously rounded measurements or combine this with AutoScaleMode.Dpi.
sealed class StudioLayout {
 sealed class Metric {public Rectangle Bounds;public Padding Padding,Margin;public Font Font;public float[] Rows,Columns;public int[] GridColumns;public int GridRow,GridHeader,ItemHeight;}
 readonly Control root;readonly Dictionary<Control,Metric> metrics=new Dictionary<Control,Metric>();readonly List<Font> fonts=new List<Font>();
 public double Factor{get;private set;}
 public StudioLayout(Control control){root=control;Factor=1;StudioVisual.Scale=1;Remember(control);}
 void Remember(Control control){var table=control as TableLayoutPanel;if(table!=null){if(table.ColumnCount==1&&table.ColumnStyles.Count==0)table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));if(table.RowCount==1&&table.RowStyles.Count==0)table.RowStyles.Add(new RowStyle(SizeType.Percent,100));}var grid=control as DataGridView;var combo=control as ComboBox;metrics[control]=new Metric{Bounds=control.Bounds,Padding=control.Padding,Margin=control.Margin,Font=control.Font,Rows=table==null?null:table.RowStyles.Cast<RowStyle>().Select(s=>s.SizeType==SizeType.Absolute?s.Height:-1).ToArray(),Columns=table==null?null:table.ColumnStyles.Cast<ColumnStyle>().Select(s=>s.SizeType==SizeType.Absolute?s.Width:-1).ToArray(),GridColumns=grid==null?null:grid.Columns.Cast<DataGridViewColumn>().Select(c=>c.AutoSizeMode==DataGridViewAutoSizeColumnMode.Fill?-1:c.Width).ToArray(),GridRow=grid==null?0:grid.RowTemplate.Height,GridHeader=grid==null?0:grid.ColumnHeadersHeight,ItemHeight=combo==null?0:combo.ItemHeight};foreach(Control child in control.Controls)Remember(child);}
 int P(double value){return (int)Math.Round(value*Factor);}
 Padding Pad(Padding value){return new Padding(P(value.Left),P(value.Top),P(value.Right),P(value.Bottom));}
 public void Apply(double scale){if(Math.Abs(scale-Factor)<.0001)return;var oldFonts=fonts.ToArray();fonts.Clear();Factor=scale;StudioVisual.Scale=(float)scale;var controls=metrics.Keys.Where(c=>!c.IsDisposed).ToArray();foreach(var c in controls)c.SuspendLayout();
  try{foreach(var c in controls){var m=metrics[c];var font=new Font(m.Font.FontFamily,(float)(m.Font.SizeInPoints*scale),m.Font.Style,GraphicsUnit.Point);fonts.Add(font);c.Font=font;c.Padding=Pad(m.Padding);c.Margin=Pad(m.Margin);var table=c as TableLayoutPanel;if(table!=null){for(int i=0;i<m.Rows.Length;i++)if(m.Rows[i]>=0)table.RowStyles[i].Height=P(m.Rows[i]);for(int i=0;i<m.Columns.Length;i++)if(m.Columns[i]>=0)table.ColumnStyles[i].Width=P(m.Columns[i]);}if(c!=root){if(c.Dock==DockStyle.None){c.Size=new Size(Math.Max(1,P(m.Bounds.Width)),Math.Max(1,P(m.Bounds.Height)));if(!(c.Parent is TableLayoutPanel)&&!(c.Parent is FlowLayoutPanel))c.Location=new Point(P(m.Bounds.X),P(m.Bounds.Y));}else if(c.Dock==DockStyle.Top||c.Dock==DockStyle.Bottom)c.Height=P(m.Bounds.Height);else if(c.Dock==DockStyle.Left||c.Dock==DockStyle.Right)c.Width=P(m.Bounds.Width);}var grid=c as DataGridView;if(grid!=null){grid.RowTemplate.Height=Math.Max(12,P(m.GridRow));grid.ColumnHeadersHeight=Math.Max(12,P(m.GridHeader));grid.DefaultCellStyle.Font=grid.ColumnHeadersDefaultCellStyle.Font=font;for(int i=0;i<m.GridColumns.Length;i++)if(m.GridColumns[i]>0)grid.Columns[i].Width=Math.Max(12,P(m.GridColumns[i]));foreach(DataGridViewRow row in grid.Rows)row.Height=grid.RowTemplate.Height;}var combo=c as ComboBox;if(combo!=null&&combo.DrawMode==DrawMode.OwnerDrawFixed)combo.ItemHeight=Math.Max(12,P(m.ItemHeight));}}
  finally{foreach(var c in controls.Reverse())c.ResumeLayout(false);root.PerformLayout();foreach(var c in controls)c.PerformLayout();root.Invalidate(true);foreach(var font in oldFonts)font.Dispose();}
 }
 public void Dispose(){foreach(var font in fonts)font.Dispose();fonts.Clear();}
}
static class StudioVisual {public static float Scale=1;}
